// Deletes raw per-run PNG renders that are not in the keep list (image budget).
// Sheets in sheets/ are always kept. Raw renders are regenerated by
// freecat.mjs / cross2d.mjs / pinning.mjs (fixed seeds).
import { readdirSync, unlinkSync } from 'node:fs';
const T = new URL('./', import.meta.url).pathname;
const keep = new Set([
  'free/sq2-ABCD-s1-view.png', 'free/sq2-ABCD-s1-slice.png', 'free/sq2-checker-s1-view.png', 'free/sq2-checker-s2-view.png',
  'free/tunnel-s1-view.png', 'free/L3-ABC-s1-slice.png', 'free/cube2-octants-s1-view.png', 'free/checker-smallA-s1-slice.png',
  'free/slab-line-s1-slice.png',
  'cross2d/sq2-ABCD-n128-s0.2-j0-seed1.png', 'cross2d/slab-line-n32-s0.2-j0-seed1.png', 'cross2d/diag-edge-diff-n32-s0.2-j0-seed1.png',
  'cross2d/checker-smallA-n64-s0.2-j0-seed1.png', 'cross2d/row-ABB-n32-s0.2-j0-seed1.png',
  'pinning/cube3-n16-s0.2-slice.png', 'pinning/cube3-n16-s0.3-slice.png',
]);
let del = 0, kept = 0;
for (const dir of ['free', 'cross2d', 'pinning', 'dbg']) {
  for (const f of readdirSync(T + dir)) {
    if (!f.endsWith('.png')) continue;
    const rel = `${dir}/${f}`;
    if (keep.has(rel)) { kept++; continue; }
    unlinkSync(T + rel); del++;
  }
}
console.log('deleted', del, 'kept', kept);
